update pkg_pack_stat
platform = #{platform}, store_url = #{storeUrl}, region_code = #{regionCode}, customer_category = #{customerCategory}, customer = #{customer}, is_replenish = #{isReplenish}, replenish_url = #{replenishUrl}, packer = #{packer}, notify_email = #{notifyEmail}, pass_date = #{passDate}, customer_use_date = #{customerUseDate}, drop_date = #{dropDate}, designer = #{designer}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id} and tenant_id = #{tenantId} and owner_user_id = #{ownerUserId}

update pkg_pack_stat
set survive_days = #{surviveDays},
    use_days = #{useDays},
    drop_date = case
        when #{dropDate} is not null and drop_date is null then #{dropDate}
        else drop_date
    end,
    update_time = now()
where id = #{id}
